/*
 * Copyright 2026 Tabsdata Inc.
 *
 * Search backed by Pagefind instead of mdbook's elasticlunr index.
 *
 * The bundle is generated by `pagefind` after each mdbook build. Under
 * `mdbook serve` the page live-reloads before the new index is written, so
 * the index is waited for briefly; without one, no search button is added.
 * The bundle path and base url are set explicitly: loaded as a module, the
 * component cannot locate itself and falls back to `/pagefind/`, which breaks
 * books not served from the site root.
 */
(function () {
    var ATTEMPTS = 20;
    var INTERVAL_MS = 500;

    var buttons = document.querySelector('#mdbook-menu-bar .left-buttons');
    if (!buttons) {
        return;
    }
    var root = new URL((typeof path_to_root === 'string' && path_to_root) || './', document.baseURI);
    var bundle = new URL('pagefind/', root);

    function mount() {
        var style = document.createElement('link');
        style.rel = 'stylesheet';
        style.href = bundle.href + 'pagefind-component-ui.css';
        document.head.appendChild(style);

        var config = document.createElement('pagefind-config');
        config.setAttribute('bundle-path', bundle.pathname);
        config.setAttribute('base-url', root.pathname);
        var trigger = document.createElement('pagefind-modal-trigger');
        trigger.setAttribute('compact', '');
        document.body.append(config, document.createElement('pagefind-modal'));
        buttons.appendChild(trigger);
    }

    function load() {
        var script = document.createElement('script');
        script.type = 'module';
        script.src = bundle.href + 'pagefind-component-ui.js';
        script.onload = mount;
        document.head.appendChild(script);
    }

    function awaitIndex(attempt) {
        fetch(bundle.href + 'pagefind-entry.json', { cache: 'no-store' })
            .then(function (response) {
                if (response.ok) {
                    load();
                } else if (attempt < ATTEMPTS) {
                    setTimeout(awaitIndex, INTERVAL_MS, attempt + 1);
                }
            })
            .catch(function () {});
    }

    awaitIndex(1);
})();
